def copiar_dados_antigos(apps, schema_editor):
    """Leva GrupoEquipeTurno e Colaborador.equipe para AlocacaoPosto (idempotente; PARADO não é migrado)."""
    Aloc = apps.get_model("organization", "AlocacaoPosto")
    Cfg = apps.get_model("organization", "GrupoEquipeTurno")
    Colab = apps.get_model("rh", "Colaborador")
    for cfg in Cfg.objects.select_related("grupo"):
        if not cfg.grupo.parent_id:
            continue  # só postos (nível 2) recebem alocações
        if cfg.situacao == "ATIVO" and cfg.responsavel_id:
            Aloc.objects.get_or_create(posto_id=cfg.grupo_id, turno=cfg.turno, colaborador_id=cfg.responsavel_id, defaults={"tipo": "PESSOA"})
        elif cfg.situacao in ("VAGO", "RESERVA"):
            if not Aloc.objects.filter(posto_id=cfg.grupo_id, turno=cfg.turno, tipo=cfg.situacao).exists():
                Aloc.objects.create(posto_id=cfg.grupo_id, turno=cfg.turno, tipo=cfg.situacao)
    for c in Colab.objects.filter(equipe__isnull=False, equipe__parent__isnull=False, is_active=True):
        if not Aloc.objects.filter(posto_id=c.equipe_id, colaborador_id=c.pk).exists():
            Aloc.objects.create(posto_id=c.equipe_id, turno=c.turno, tipo="PESSOA", colaborador_id=c.pk)


